import java.io.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    public static void main(String[] args) throws IOException {
        int p = (int) nextLong(), n = (int) nextLong();
        // Keep the cheapest quote per project.
        long[] best = new long[p];
        boolean[] has = new boolean[p];
        for (int i = 0; i < n; i++) {
            int id = (int) nextLong();
            long v = nextLong();
            if (!has[id] || v < best[id]) { best[id] = v; has[id] = true; }
        }
        long total = 0;
        for (int i = 0; i < p; i++) {
            if (!has[i]) { System.out.println(-1); return; }
            total += best[i];
        }
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	p, n := int(readInt()), int(readInt())
	// Keep the cheapest quote per project.
	best := make([]int64, p)
	has := make([]bool, p)
	for i := 0; i < n; i++ {
		id := int(readInt())
		v := readInt()
		if !has[id] || v < best[id] {
			best[id] = v
			has[id] = true
		}
	}
	var total int64
	for i := 0; i < p; i++ {
		if !has[i] {
			fmt.Println(-1)
			return
		}
		total += best[i]
	}
	fmt.Println(total)
}
